/* @autogenerated */
package net.civeira.phylax.features.document.rendering.infrastructure.handlebars;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import com.github.jknack.handlebars.Handlebars;
import com.github.jknack.handlebars.Template;
import com.github.jknack.handlebars.io.AbstractTemplateLoader;
import com.github.jknack.handlebars.io.StringTemplateSource;

import jakarta.enterprise.context.ApplicationScoped;
import net.civeira.phylax.features.document.rendering.domain.RenderedAsset;
import net.civeira.phylax.features.document.rendering.domain.RenderedTemplate;
import net.civeira.phylax.features.document.rendering.domain.TemplateOutputFormat;
import net.civeira.phylax.features.document.rendering.domain.TemplateRenderRequest;
import net.civeira.phylax.features.document.rendering.domain.gateway.TemplateRenderGateway;

/**
 * Rendering engine adapter backed by Handlebars (jknack/handlebars.java).
 *
 * <p>
 * Receives pre-resolved raw content strings, snippets and merged variables from the use case and
 * performs purely technical string substitution. Contains no domain logic.
 *
 * <h3>Syntax supported in templates</h3>
 * <ul>
 * <li>{@code {{variable}}} — HTML-escaped variable substitution</li>
 * <li>{@code {{object.field}}} — nested property access (dotted keys expanded to nested maps)</li>
 * <li>{@code {{{rawHtml}}}} — unescaped HTML injection</li>
 * <li>{@code {{>HEADER}}} — snippet partial (resolved from the snippets map)</li>
 * </ul>
 */
@ApplicationScoped
public class HandlebarsTemplateRenderAdapter implements TemplateRenderGateway {

  @Override
  public RenderedTemplate render(final TemplateRenderRequest request) {
    Handlebars handlebars = buildHandlebars(request.getSnippets());
    Map<String, Object> context = toNestedMap(request.getVariables());

    String subject =
        request.getSubject() != null ? compile(handlebars, request.getSubject(), context) : null;
    String html = compile(handlebars, request.getHtmlContent(), context);
    String text =
        request.getTextContent() != null ? compile(handlebars, request.getTextContent(), context)
            : null;

    List<RenderedAsset> outputAssets = new ArrayList<>(request.getAssets());
    if (TemplateOutputFormat.HTML_EMBEDDED == request.getOutputFormat()) {
      html = inlineCssAssets(html, outputAssets);
    }

    return RenderedTemplate.builder().subject(subject).htmlContent(html).textContent(text)
        .assets(outputAssets).build();
  }

  // ---------------------------------------------------------------------------
  // Private helpers
  // ---------------------------------------------------------------------------

  /**
   * Inlines all CSS assets from {@code assets} into the {@code <head>} of the given HTML as
   * {@code <style>} blocks. Each inlined asset is replaced in the list with a copy that has
   * {@code embedded = true} so callers know it no longer needs to be linked externally.
   *
   * <p>
   * If the HTML has no {@code <head>} tag the style block is prepended to the document.
   * </p>
   */
  private String inlineCssAssets(final String html, final List<RenderedAsset> assets) {
    List<RenderedAsset> cssAssets = assets.stream()
        .filter(a -> "text/css".equalsIgnoreCase(a.getContentType())).filter(a -> !a.isEmbedded())
        .filter(a -> a.getContent() != null && !a.getContent().isBlank())
        .collect(Collectors.toList());

    if (cssAssets.isEmpty()) {
      return html;
    }

    String styleBlock = cssAssets.stream().map(a -> "<style>" + a.getContent() + "</style>")
        .collect(Collectors.joining("\n"));

    // Replace non-embedded CSS assets with their embedded counterparts
    cssAssets.forEach(asset -> {
      int idx = assets.indexOf(asset);
      assets.set(idx, RenderedAsset.builder().code(asset.getCode())
          .contentType(asset.getContentType()).content(asset.getContent()).embedded(true).build());
    });

    int headClose = html.indexOf("</head>");
    if (headClose >= 0) {
      return html.substring(0, headClose) + styleBlock + "\n" + html.substring(headClose);
    }
    return styleBlock + "\n" + html;
  }

  /**
   * Builds a {@link Handlebars} instance whose partial loader resolves {@code {{>partialName}}}
   * against the preloaded snippets map.
   */
  private Handlebars buildHandlebars(final Map<String, String> snippets) {
    AbstractTemplateLoader loader = new AbstractTemplateLoader() {
      @Override
      public StringTemplateSource sourceAt(final String location) {
        return new StringTemplateSource(location, snippets.getOrDefault(location, ""));
      }
    };
    return new Handlebars(loader);
  }

  private String compile(final Handlebars handlebars, final String content,
      final Map<String, Object> context) {
    try {
      Template template = handlebars.compileInline(content);
      return template.apply(context);
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  /**
   * Expands flat dotted-key entries (e.g. {@code "user.name" -> "Alice"}) into nested maps
   * ({@code {user: {name: "Alice"}}}) so Handlebars resolves {@code {{user.name}}} correctly.
   */
  @SuppressWarnings("unchecked")
  private Map<String, Object> toNestedMap(final Map<String, String> flat) {
    Map<String, Object> root = new LinkedHashMap<>();
    for (Map.Entry<String, String> entry : flat.entrySet()) {
      String[] parts = entry.getKey().split("\\.", -1);
      Map<String, Object> current = root;
      for (int i = 0; i < parts.length - 1; i++) {
        current =
            (Map<String, Object>) current.computeIfAbsent(parts[i], _ -> new LinkedHashMap<>());
      }
      current.put(parts[parts.length - 1], entry.getValue());
    }
    return root;
  }
}
